import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getWarehouseInfo, getProductsForWarehouse, getProducts} from '../data/dataFetching';
import './warehouseInfo.css';

// ADD PRODUCT HANDLING MUST BE RECODED/CHEKED IN TIME OF BACKEND DEVELOPMENT. 
// Right now product is not adds to table when it is added throught the modal.

function WarehouseInfo() {

  const { id } = useParams(); // Get the warehouse ID from the URL parameters
  const navigate = useNavigate(); // Initialize the navigate function for navigation
  
  const [warehouseInfo, setWarehouseInfo] = useState([]);
  const [productsWarehouse, setproductsWarehouse] = useState([]);
  const [allProducts, setAllProducts] = useState([]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const [isDeleteMessageOpen, setIsDeleteMessageOpen] = useState(false);

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newProduct, setNewProduct] = useState({ product_id: '', w_quantity: '', location: '' });


  useEffect(() => {
    getWarehouseInfo(id).then(data => setWarehouseInfo(data));
    getProductsForWarehouse(id).then(data => setproductsWarehouse(data));
    getProducts().then(data => setAllProducts(data));
  }, [id]);

  
  let [search, setSearch] = useState("")

  {/*
    The handleEditClick function sets the selected product and opens the modal.
    The handleModalClose function closes the modal and resets the selected product.
    The handleFormSubmit function updates the w_quantity and location fields of the selected product and closes the modal.
    The handleInputChange function updates the state of the selected product as the user types in the input fields.
    The modal is styled using CSS to appear as a popup window.
    */}

  const handleEditClick = (product) => {
    setSelectedProduct(product);
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
      setIsModalOpen(false);
      setSelectedProduct(null);
  };

  const handleFormSubmit = (e) => {
      e.preventDefault();
      const updatedProducts = productsWarehouse.map(product =>
          product.product_id === selectedProduct.product_id ? selectedProduct : product
      );
      setproductsWarehouse(updatedProducts);
      handleModalClose();
  };

  const handleInputChange = (e) => {
      const { name, value } = e.target;
      setSelectedProduct(prevState => ({
          ...prevState,
          [name]: value
      }));
  };

  {/*
    Delete handler function: checks the quantity and deletes the product if the quantity is 0.
    If the quantity is not 0, it opens a modal with a message.
  */}

  const handleDeleteClick = (product) => {
    if (product.w_quantity === 0) {
      setproductsWarehouse(prevProducts =>
          prevProducts.filter(p => p.product_id !== product.product_id)
      );
    } else {
      setIsDeleteMessageOpen(true);
    }
  };

  const handleDeleteMessageClose = () => {
    setIsDeleteMessageOpen(false);
  };

  {/*
    Add product modal handling
  */}
  const handleAddProductClick = () => {
    setIsAddModalOpen(true);
  };

  const handleAddModalClose = () => {
    setIsAddModalOpen(false);
    setNewProduct({ product_id: '', w_quantity: '', location: '' });
  };

  const handleAddFormSubmit = (e) => {
    e.preventDefault();
    const productToAdd = allProducts.find(product => product.product_id === newProduct.product_id);
    const newProductWithDetails = {
      ...productToAdd,
      w_quantity: newProduct.w_quantity,
      location: newProduct.location
    };
    setproductsWarehouse([...productsWarehouse, newProductWithDetails]);
    handleAddModalClose();
  };

  const handleNewProductChange = (e) => {
    const { name, value } = e.target;
    setNewProduct(prevState => ({
      ...prevState,
      [name]: value
    }));
  };






  {/*Search for table*/}
  const handleSearchChange = (e) => {
    setSearch(e.target.value);
  };

  const filteredProducts = productsWarehouse.filter(product =>
    product.name && product.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="warehouse-info-container">
      <div className='warehouse-info'>

        {warehouseInfo.map(warehouse => (
            <>
              <h1 key={warehouse.warehouse_id}>{warehouse.warehouse_name}</h1>

              <div key={warehouse.warehouse_id}>
                <h4>Address:</h4>
                <p>{warehouse.address}</p>
              </div>
            
            </>
        ))}

      </div>

      <div className='warehouse-stock'>


        <div className="table-container">

          <h3 className='mt-1'>Provided products</h3>

          <div className="tableFunctions">

            <div className="tableSeachbar mb-3">
                <i class="bi bi-search"></i>
                <input class="tableSeachInput" type="text" placeholder="Search" onChange={handleSearchChange} value={search}></input>
            </div>

            <div>
              <button className="addBtn" onClick={handleAddProductClick}>Add Product</button>
            </div>

          </div>

          <table>
            <thead>
              <tr>
                <th>ProductID</th>
                <th>Image</th>
                <th>Name</th>
                <th>Quantity</th>
                <th>Unit</th>
                <th>Location</th>
                <th></th>
                <th></th>
              </tr>
            </thead>

            <tbody>
              {filteredProducts.map(product => (
            
                <tr>
                  <td>{product.product_id}</td>
                  <td><span className={product.product_picture}></span></td>
                  <td>{product.name}</td>
                  <td>{product.w_quantity}</td>
                  <td>{product.unit}</td>
                  <td>{product.location}</td>
                  <td>
                      <button className="table-btn edit-btn"onClick={() => handleEditClick(product)}>
                        <i className="bi bi-pencil-square"></i>
                      </button>
                    </td>
                    <td>
                      <button className="table-btn delete-btn" onClick={() => handleDeleteClick(product)}>
                        <i className="bi bi-trash"></i>
                      </button>
                    </td>
                </tr>
                
              ))}
            </tbody>
          </table>

        </div>

      </div>

      {/* Edit product modal */}

      {isModalOpen && (
        <div className="modal">
            <div className="modal-content">
                <span className="close" onClick={handleModalClose}>&times;</span>
                <h2>Edit Product</h2>
                <form onSubmit={handleFormSubmit}>
                    <div className="form-group">
                        <label htmlFor="w_quantity">Quantity:</label>
                        <input
                            type="number"
                            id="w_quantity"
                            name="w_quantity"
                            value={selectedProduct.w_quantity}
                            onChange={handleInputChange}
                        />
                    </div>
                    <div className="form-group">
                        <label htmlFor="location">Location:</label>
                        <input
                            type="text"
                            id="location"
                            name="location"
                            value={selectedProduct.location}
                            onChange={handleInputChange}
                        />
                    </div>
                    <button type="submit">Save</button>
                </form>
            </div>
        </div>
      )}
      {/* Delete message modal */}
      {isDeleteMessageOpen && (
        <div className="modal">
            <div className="modal-content">
                <span className="close" onClick={handleDeleteMessageClose}>&times;</span>
                <h2>Delete Error</h2>
                <p>The product cannot be deleted until the quantity of it for this warehouse is 0.</p>
                <button className='deleteErrorBtn' onClick={handleDeleteMessageClose}>Close</button>
            </div>
        </div>
      )}

      {/* Add product modal */}
      {isAddModalOpen && (
        <div className="modal">
          <div className="modal-content">
            <span className="close" onClick={handleAddModalClose}>&times;</span>
            <h2>Add Product</h2>
            <form onSubmit={handleAddFormSubmit}>
              <div className="form-group">
                <label htmlFor="product_id">Choose Product:</label>
                <select
                  id="product_id"
                  name="product_id"
                  value={newProduct.product_id}
                  onChange={handleNewProductChange}
                >
                  <option value="">Select a product</option>
                  {allProducts.length > 0 ? (
                    allProducts.map(product => (
                      <option key={product.product_id} value={product.product_id}>
                        {product.name}
                      </option>
                    ))
                  ) : (
                    <option value="" disabled>No products available</option>
                  )}
                </select>
              </div>
              <div className="form-group">
                <label htmlFor="w_quantity">Quantity:</label>
                <input
                  type="number"
                  id="w_quantity"
                  name="w_quantity"
                  value={newProduct.w_quantity}
                  onChange={handleNewProductChange}
                />
              </div>
              <div className="form-group">
                <label htmlFor="location">Location:</label>
                <input
                  type="text"
                  id="location"
                  name="location"
                  value={newProduct.location}
                  onChange={handleNewProductChange}
                />
              </div>
              <button type="submit">Add</button>
            </form>
          </div>
        </div>
      )}

    </div>
  )
}

export default WarehouseInfo;
